import { toast } from 'cbdc-react-toastify';
import { delay } from 'es-toolkit';
import { TEST_INTRO } from '~/shared/config/environment';

export const snackBar = (text: string, autoCloseMs: number = 2000) => {
  toast(text, { containerId: 'snackbar', autoClose: autoCloseMs });
};

export const notiBar = (text: string, autoCloseMs: number = 3000) => {
  toast(text, { containerId: 'notibar', autoClose: autoCloseMs });
};

export const devNotiBar = async (text: string, delayMs: number = 1000, autoCloseMs: number = 2000) => {
  if (TEST_INTRO) {
    notiBar(text, autoCloseMs);
    if (delayMs) {
      await delay(delayMs);
    }
  }
};

export const devSnackBar = async (text: string, delayMs: number = 1000, autoCloseMs: number = 1000) => {
  if (TEST_INTRO) {
    snackBar(text, autoCloseMs);
    if (delayMs) {
      await delay(delayMs);
    }
    toast.dismiss({ containerId: 'snackbar' });
  }
};
